//! The repositories of the "countries" table. Repositories decide nothing.

use async_trait::async_trait;
use crate::bson_values;
use crate::bson_values::Loaded;
use crate::common::Page;
use crate::database::Db;
use crate::entities::country::Country;
use crate::errors::DomainError;
use mongodb::bson::doc;
use std::cmp::Ordering;
use std::sync::{Arc, Mutex};

/// Where countries rows are kept. Services depend only on this trait.
#[async_trait]
pub trait CountryRepository: Send + Sync {
    /// The row with this primary key, or None.
    async fn find_by_document_id(&self, document_id: String) -> Result<Option<Country>, DomainError>;

    /// At most limit rows from offset, by primary key, and how many there are.
    async fn list(&self, offset: u64, limit: u64) -> Result<Page<Country>, DomainError>;

    /// The row with this id, or None.
    async fn find_by_id(&self, id: f64) -> Result<Option<Country>, DomainError>;

    /// Stores a new row; the values the database fills are read back.
    async fn insert(&self, entity: Country) -> Result<Country, DomainError>;

    /// Stores the changes made to a row.
    async fn update(&self, entity: Country) -> Result<Country, DomainError>;

    /// Removes a row.
    async fn delete(&self, entity: &Country) -> Result<(), DomainError>;
}

/// Keeps countries rows in the database, through the MongoDB driver: on the connection of the unit of work, or in its transaction.
pub struct MongoCountryRepository<'a> {
    db: &'a Db,
}

impl<'a> MongoCountryRepository<'a> {
    pub fn new(db: &'a Db) -> Self {
        Self { db }
    }
}

#[async_trait]
impl CountryRepository for MongoCountryRepository<'_> {
    async fn find_by_document_id(&self, document_id: String) -> Result<Option<Country>, DomainError> {
        let found = self.db.find_one("countries", doc! { "_id": bson_values::of_text(&document_id)? }).await?;
        Ok(found.as_ref().map(Country::from_document).transpose()?)
    }

    async fn list(&self, offset: u64, limit: u64) -> Result<Page<Country>, DomainError> {
        let total = self.db.count("countries", doc! {}).await?;
        let found = if limit > 0 {
            self.db.find("countries", doc! {}, doc! { "_id": 1 }, offset, limit).await?
        } else {
            Vec::new()
        };
        Ok(Page { items: found.iter().map(Country::from_document).collect::<Result<_, _>>()?, total, offset, limit })
    }

    async fn find_by_id(&self, id: f64) -> Result<Option<Country>, DomainError> {
        let found = self.db.find_one("countries", doc! { "id": bson_values::of_f64(&id)? }).await?;
        Ok(found.as_ref().map(Country::from_document).transpose()?)
    }

    async fn insert(&self, entity: Country) -> Result<Country, DomainError> {
        let mut entity = entity;
        let document = entity.to_document()?;
        self.db.insert("Country", "countries", &document).await?;
        entity.loaded_document = Loaded(Some(document));
        Ok(entity)
    }

    async fn update(&self, entity: Country) -> Result<Country, DomainError> {
        let mut entity = entity;
        let now = entity.to_document()?;
        let changes = bson_values::changes(entity.loaded_document.0.as_ref(), &now, &["id", "name"]);
        if !changes.is_empty() {
            self.db.update("Country", "countries", doc! { "_id": now.get("_id").cloned() }, changes).await?;
        }
        entity.loaded_document = Loaded(Some(now));
        Ok(entity)
    }

