//! The repositories of the "products" table. Repositories decide nothing.

use async_trait::async_trait;
use crate::bson_values;
use crate::bson_values::Loaded;
use crate::common::Page;
use crate::database::Db;
use crate::entities::product::Product;
use crate::errors::DomainError;
use mongodb::bson::doc;
use std::cmp::Ordering;
use std::sync::{Arc, Mutex};

/// Where products rows are kept. Services depend only on this trait.
#[async_trait]
pub trait ProductRepository: Send + Sync {
    /// The row with this primary key, or None.
    async fn find_by_id(&self, id: String) -> Result<Option<Product>, DomainError>;

    /// At most limit rows from offset, by primary key, and how many there are.
    async fn list(&self, offset: u64, limit: u64) -> Result<Page<Product>, DomainError>;

    /// The row with this sku, or None.
    async fn find_by_sku(&self, sku: String) -> Result<Option<Product>, DomainError>;

    /// Rows with this title, by primary key.
    async fn find_all_by_title(&self, title: String) -> Result<Vec<Product>, DomainError>;

    /// Stores a new row; the values the database fills are read back.
    async fn insert(&self, entity: Product) -> Result<Product, DomainError>;

    /// Stores the changes made to a row.
    async fn update(&self, entity: Product) -> Result<Product, DomainError>;

    /// Removes a row.
    async fn delete(&self, entity: &Product) -> Result<(), DomainError>;

    /// Adds an item to related, and gives the row as it is then, if there is one.
    async fn add_related(&self, id: String, related: String) -> Result<Option<Product>, DomainError>;

    /// Removes an item from related, and gives the row as it is then, if there is one.
    async fn remove_related(&self, id: String, related: String) -> Result<Option<Product>, DomainError>;
}

/// Keeps products rows in the database, through the MongoDB driver: on the connection of the unit of work, or in its transaction.
pub struct MongoProductRepository<'a> {
    db: &'a Db,
}

impl<'a> MongoProductRepository<'a> {
    pub fn new(db: &'a Db) -> Self {
        Self { db }
    }
}

#[async_trait]
impl ProductRepository for MongoProductRepository<'_> {
    async fn find_by_id(&self, id: String) -> Result<Option<Product>, DomainError> {
        if !bson_values::is_object_id(&id) {
            return Ok(None);
        }
        let found = self.db.find_one("products", doc! { "_id": bson_values::of_object_id(&id)? }).await?;
        Ok(found.as_ref().map(Product::from_document).transpose()?)
    }

    async fn list(&self, offset: u64, limit: u64) -> Result<Page<Product>, DomainError> {
        let total = self.db.count("products", doc! {}).await?;
        let found = if limit > 0 {
            self.db.find("products", doc! {}, doc! { "_id": 1 }, offset, limit).await?
        } else {
            Vec::new()
        };
        Ok(Page { items: found.iter().map(Product::from_document).collect::<Result<_, _>>()?, total, offset, limit })
    }

    async fn find_by_sku(&self, sku: String) -> Result<Option<Product>, DomainError> {
        let found = self.db.find_one("products", doc! { "sku": bson_values::of_text(&sku)? }).await?;
        Ok(found.as_ref().map(Product::from_document).transpose()?)
    }

    async fn find_all_by_title(&self, title: String) -> Result<Vec<Product>, DomainError> {
        let found = self.db.find("products", doc! { "title": bson_values::of_text(&title)? }, doc! { "_id": 1 }, 0, 0).await?;
        Ok(found.iter().map(Product::from_document).collect::<Result<_, _>>()?)
    }

    async fn insert(&self, entity: Product) -> Result<Product, DomainError> {
        let mut entity = entity;
        entity.id = entity.id.or_else(|| Some(mongodb::bson::oid::ObjectId::new().to_hex()));
        entity.stock = entity.stock.or_else(|| Some(0.0));
        let document = entity.to_document()?;
        self.db.insert("Product", "products", &document).await?;
        entity.loaded_document = Loaded(Some(document));
        Ok(entity)
    }

    async fn update(&self, entity: Product) -> Result<Product, DomainError> {
        let mut entity = entity;
        let now = entity.to_document()?;
        let changes = bson_values::changes(entity.loaded_document.0.as_ref(), &now, &["sku", "title", "price", "stock", "reference", "picture", "related"]);
        if !changes.is_empty() {
            self.db.update("Product", "products", doc! { "_id": now.get("_id").cloned() }, changes).await?;
        }
        entity.loaded_document = Loaded(Some(now));
        Ok(entity)
    }

    async fn delete(&self, entity: &Product) -> Result<(), DomainError> {
        let id = entity.id.clone().expect("id is set");
        self.db.delete("Product", "products", doc! { "_id": bson_values::of_object_id(&id)? }).await
    }

    async fn add_related(&self, id: String, related: String) -> Result<Option<Product>, DomainError> {
        if !bson_values::is_object_id(&id) {
            return Ok(None);
        }
        let change = doc! { "$push": { "related": bson_values::of_object_id(&related)? } };
        let changed = self.db.change("Product", "products", doc! { "_id": bson_values::of_object_id(&id)? }, change).await?;
        Ok(changed.as_ref().map(Product::from_document).transpose()?)
    }

    async fn remove_related(&self, id: String, related: String) -> Result<Option<Product>, DomainError> {
        if !bson_values::is_object_id(&id) {
            return Ok(None);
        }
        let change = doc! { "$pull": { "related": bson_values::of_object_id(&related)? } };
        let changed = self.db.change("Product", "products", doc! { "_id": bson_values::of_object_id(&id)? }, change).await?;
        Ok(changed.as_ref().map(Product::from_document).transpose()?)
    }
}

/// Keeps products rows in memory, for tests and for trying the services without a database. Its copies share the rows.
#[derive(Clone, Default)]
pub struct MemoryProductRepository {
    rows: Arc<Mutex<Vec<Product>>>,
}

impl MemoryProductRepository {
    /// The rows reads see, by primary key.
    fn visible(&self) -> Vec<Product> {
        let mut rows: Vec<Product> = self.rows.lock().unwrap().iter().cloned().collect();
        rows.sort_by(|a, b| key_of(a).partial_cmp(&key_of(b)).unwrap_or(Ordering::Equal));
        rows
    }

    /// Keeps a row, in place of the one with its key.
    fn store(&self, entity: &Product) {
        let mut rows = self.rows.lock().unwrap();
        rows.retain(|row| key_of(row) != key_of(entity));
        rows.push(entity.clone());
    }
}

/// The key of a row, as a tuple of its key values.
fn key_of(row: &Product) -> (Option<String>,) {
    (row.id.clone(),)
}

#[async_trait]
impl ProductRepository for MemoryProductRepository {
    async fn find_by_id(&self, id: String) -> Result<Option<Product>, DomainError> {
        Ok(self.visible().into_iter().find(|row| row.id.as_ref() == Some(&id)))
    }

    async fn list(&self, offset: u64, limit: u64) -> Result<Page<Product>, DomainError> {
        let rows = self.visible();
        let total = rows.len() as u64;
        Ok(Page { items: rows.into_iter().skip(offset as usize).take(limit as usize).collect(), total, offset, limit })
    }

    async fn find_by_sku(&self, sku: String) -> Result<Option<Product>, DomainError> {
        Ok(self.visible().into_iter().find(|row| row.sku.as_ref() == Some(&sku)))
    }

    async fn find_all_by_title(&self, title: String) -> Result<Vec<Product>, DomainError> {
        Ok(self.visible().into_iter().filter(|row| row.title.as_ref() == Some(&title)).collect())
    }

    async fn insert(&self, entity: Product) -> Result<Product, DomainError> {
        let mut entity = entity;
        entity.id = entity.id.or_else(|| Some(mongodb::bson::oid::ObjectId::new().to_hex()));
        entity.stock = entity.stock.or_else(|| Some(0.0));
        self.store(&entity);
        Ok(entity)
    }

    async fn update(&self, entity: Product) -> Result<Product, DomainError> {
        self.store(&entity);
        Ok(entity)
    }

    async fn delete(&self, entity: &Product) -> Result<(), DomainError> {
        self.rows.lock().unwrap().retain(|row| key_of(row) != key_of(entity));
        Ok(())
    }

    async fn add_related(&self, id: String, related: String) -> Result<Option<Product>, DomainError> {
        let Some(mut found) = self.visible().into_iter().find(|row| row.id.as_ref() == Some(&id)) else {
            return Ok(None);
        };
        found.related.get_or_insert_default().push(related);
        self.store(&found);
        Ok(Some(found))
    }

    async fn remove_related(&self, id: String, related: String) -> Result<Option<Product>, DomainError> {
        let Some(mut found) = self.visible().into_iter().find(|row| row.id.as_ref() == Some(&id)) else {
            return Ok(None);
        };
        found.related.get_or_insert_default().retain(|item| *item != related);
        self.store(&found);
        Ok(Some(found))
    }
}

