//! The repository of the "countries" table, against the test database.

use mongorust_mongodb_repositories_only::unit_of_work::UnitOfWork;
use super::{database, factories};

#[tokio::test]
async fn is_stored_and_read_back() {
    let (_turn, uow) = database::open().await;
    let stored = factories::add_country(&uow, 1).await;
    let found = uow.countries().find_by_document_id(stored.document_id.clone().expect("document_id is set")).await.expect("a read").expect("the row");
    assert_eq!(stored.document_id, found.document_id);
    assert!(uow.countries().find_by_id(stored.id.expect("id is set")).await.expect("a read").is_some());
}

#[tokio::test]
async fn lists_rows_by_key() {
    let (_turn, uow) = database::open().await;
    factories::add_country(&uow, 1).await;
    factories::add_country(&uow, 2).await;
    let page = uow.countries().list(0, 1).await.expect("a page");
    assert_eq!(2, page.total);
    assert_eq!(1, page.items.len());
}

#[tokio::test]
async fn stores_the_changes() {
    let (_turn, uow) = database::open().await;
    let mut stored = factories::add_country(&uow, 1).await;
    stored.name = Some("changed".to_string());
    uow.countries().update(stored.clone()).await.expect("an update");
    let found = uow.countries().find_by_document_id(stored.document_id.clone().expect("document_id is set")).await.expect("a read");
    assert_eq!(Some("changed".to_string()), found.and_then(|row| row.name));
}

#[tokio::test]
async fn is_deleted() {
    let (_turn, uow) = database::open().await;
    let stored = factories::add_country(&uow, 1).await;
    uow.countries().delete(&stored).await.expect("a delete");
    assert!(uow.countries().find_by_document_id(stored.document_id.clone().expect("document_id is set")).await.expect("a read").is_none());
}

