//! The repository of the "customers" table, against the test database.

use mongorust_mongodb_repositories_only::unit_of_work::UnitOfWork;
use super::{database, factories};

#[tokio::test]
async fn is_stored_and_read_back() {
    let (_turn, uow) = database::open().await;
    let stored = factories::add_customer(&uow, 1).await;
    let found = uow.customers().find_by_id(stored.id.clone().expect("id is set")).await.expect("a read").expect("the row");
    assert_eq!(stored.id, found.id);
    assert!(uow.customers().find_by_email(stored.email.clone().expect("email is set")).await.expect("a read").is_some());
}

#[tokio::test]
async fn lists_rows_by_key() {
    let (_turn, uow) = database::open().await;
    factories::add_customer(&uow, 1).await;
    factories::add_customer(&uow, 2).await;
    let page = uow.customers().list(0, 1).await.expect("a page");
    assert_eq!(2, page.total);
    assert_eq!(1, page.items.len());
}

#[tokio::test]
async fn adds_and_removes_one_item_of_tags() {
    let (_turn, uow) = database::open().await;
    let stored = factories::add_customer(&uow, 1).await;
    let before = stored.tags.as_ref().map_or(0, Vec::len);
    let n = 7;
    let item: String = format!("tags-{n}");
    let added = uow.customers().add_tag(stored.id.clone().expect("id is set"), item.clone()).await.expect("a write").expect("the row");
    assert_eq!(before + 1, added.tags.as_ref().map_or(0, Vec::len));
    let removed = uow.customers().remove_tag(stored.id.clone().expect("id is set"), item).await.expect("a write").expect("the row");
    assert_eq!(before, removed.tags.as_ref().map_or(0, Vec::len));
}

