//! The test database: the MongoDB database TEST_DATABASE_URL names, with every collection created empty before every test.

use mongodb::{Database, IndexModel};
use mongodb::bson::{Document, doc};
use mongodb::options::IndexOptions;
use mongorust_mongodb_repositories_only::database::database_at;
use mongorust_mongodb_repositories_only::unit_of_work::MongoUnitOfWork;
use tokio::sync::{Mutex, MutexGuard};

/// Every test empties the same database: they take turns
static TURN: Mutex<()> = Mutex::const_new(());

/// The test database.
pub async fn connect() -> Database {
    let url = std::env::var("TEST_DATABASE_URL").expect(
        "The database tests need a disposable MongoDB database (a replica set, for its transactions): set TEST_DATABASE_URL (it is emptied)",
    );
    database_at(&url).await.expect("the test database")
}

/// The repositories over the test database, with its collections and their indexes created again, and the turn of the
/// test that holds it.
pub async fn open() -> (MutexGuard<'static, ()>, MongoUnitOfWork) {
    let turn = TURN.lock().await;
    let database = connect().await;
    database.drop().await.expect("an empty database");
    database.create_collection("customers").await.expect("a collection");
    database.create_collection("products").await.expect("a collection");
    database.create_collection("orders").await.expect("a collection");
    database.create_collection("countries").await.expect("a collection");
    let index = IndexModel::builder().keys(doc! { "email": 1 }).options(IndexOptions::builder().unique(true).build()).build();
    database.collection::<Document>("customers").create_index(index).await.expect("an index");
    let index = IndexModel::builder().keys(doc! { "sku": 1 }).options(IndexOptions::builder().unique(true).build()).build();
    database.collection::<Document>("products").create_index(index).await.expect("an index");
    let index = IndexModel::builder().keys(doc! { "title": 1 }).build();
    database.collection::<Document>("products").create_index(index).await.expect("an index");
    let index = IndexModel::builder().keys(doc! { "year": 1, "number": 1 }).options(IndexOptions::builder().unique(true).build()).build();
    database.collection::<Document>("orders").create_index(index).await.expect("an index");
    let index = IndexModel::builder().keys(doc! { "customer": 1 }).build();
    database.collection::<Document>("orders").create_index(index).await.expect("an index");
    let index = IndexModel::builder().keys(doc! { "id": 1 }).options(IndexOptions::builder().unique(true).build()).build();
    database.collection::<Document>("countries").create_index(index).await.expect("an index");
    (turn, MongoUnitOfWork::new(database))
}

#[tokio::test]
async fn is_the_one_test_database_url_names() {
    let _turn = TURN.lock().await;
    let url = std::env::var("TEST_DATABASE_URL").expect("TEST_DATABASE_URL");
    let name = url.rsplit('/').next().and_then(|name| name.split('?').next());
    assert_eq!(name, Some(connect().await.name()));
}

