//! Rows for the tests: valid values for every column, and the rows they point to.

// Not every test uses every factory
#![allow(dead_code)]

use mongorust_mongodb_repositories_only::entities::country::Country;
use mongorust_mongodb_repositories_only::entities::customer::Customer;
use mongorust_mongodb_repositories_only::entities::order::Order;
use mongorust_mongodb_repositories_only::entities::product::Product;
use mongorust_mongodb_repositories_only::unit_of_work::UnitOfWork;

/// A valid Customer that is not stored yet; n makes its unique values differ.
pub fn new_customer(n: i32) -> Customer {
    Customer {
        email: Some(format!("email-{n}")),
        name: Some(format!("name-{n}")),
        password_hash: Some(format!("passwordhash-{n}")),
        active: Some(true),
        level: Some("basic".to_string()),
        address: Some(new_customer_address(n)),
        tags: Some(Vec::new()),
        preferences: Some(new_customer_preferences(n)),
        extra: Some(mongodb::bson::bson!({ "n": n })),
        updated_at: Some(chrono::NaiveDate::from_ymd_opt(2026, 1, (n % 28 + 1) as u32).expect("a date").and_hms_opt(12, 0, 0).expect("a time").and_utc()),
        ..Default::default()
    }
}

/// A stored Customer.
pub async fn add_customer(uow: &dyn UnitOfWork, n: i32) -> Customer {
    let entity = new_customer(n);
    uow.customers().insert(entity).await.expect("a stored Customer")
}

/// A valid CustomerAddress; n makes its values differ.
pub fn new_customer_address(n: i32) -> mongorust_mongodb_repositories_only::entities::customer::CustomerAddress {
    mongorust_mongodb_repositories_only::entities::customer::CustomerAddress {
        street: Some(format!("street-{n}")),
        city: Some(format!("city-{n}")),
        zip_code: Some(format!("zipcode-{n}")),
        location: Some(new_customer_address_location(n)),
        ..Default::default()
    }
}

/// A valid CustomerAddressLocation; n makes its values differ.
pub fn new_customer_address_location(_n: i32) -> mongorust_mongodb_repositories_only::entities::customer::CustomerAddressLocation {
    mongorust_mongodb_repositories_only::entities::customer::CustomerAddressLocation {
        r#type: Some("Point".to_string()),
        coordinates: Some(Vec::new()),
        ..Default::default()
    }
}

/// A valid CustomerPreferences; n makes its values differ.
pub fn new_customer_preferences(n: i32) -> mongorust_mongodb_repositories_only::entities::customer::CustomerPreferences {
    mongorust_mongodb_repositories_only::entities::customer::CustomerPreferences {
        theme: Some(format!("theme-{n}")),
        newsletter: Some(true),
        ..Default::default()
    }
}

/// A valid Product that is not stored yet; n makes its unique values differ.
pub fn new_product(n: i32) -> Product {
    Product {
        sku: Some(format!("sku-{n}")),
        title: Some(format!("title-{n}")),
        price: Some(rust_decimal::Decimal::new(i64::from(n % 10000) * 100 + 50, 2)),
        stock: Some(f64::from(n) + 0.5),
        reference: Some(uuid::Uuid::from_u128(n as u128)),
        picture: Some(vec![n as u8]),
        related: Some(Vec::new()),
        ..Default::default()
    }
}

/// A stored Product.
pub async fn add_product(uow: &dyn UnitOfWork, n: i32) -> Product {
    let entity = new_product(n);
    uow.products().insert(entity).await.expect("a stored Product")
}

/// A valid Order that is not stored yet; n makes its unique values differ.
pub fn new_order(n: i32) -> Order {
    Order {
        number: Some(f64::from(n) + 0.5),
        year: Some(f64::from(n) + 0.5),
        lines: Some(vec![new_order_line(n)]),
        notes: Some(vec![new_order_note(n)]),
        ..Default::default()
    }
}

/// A stored Order, with the rows it points to.
pub async fn add_order(uow: &dyn UnitOfWork, n: i32) -> Order {
    let parent0 = add_customer(uow, n).await;
    let mut entity = new_order(n);
    entity.customer = parent0.id.clone();
    uow.orders().insert(entity).await.expect("a stored Order")
}

/// A valid OrderLine; n makes its values differ.
pub fn new_order_line(n: i32) -> mongorust_mongodb_repositories_only::entities::order::OrderLine {
    mongorust_mongodb_repositories_only::entities::order::OrderLine {
        product: Some(format!("{n:024x}")),
        quantity: Some(f64::from(1 + n) + 0.5),
        price: Some(rust_decimal::Decimal::new(i64::from(n % 10000) * 100 + 50, 2)),
        status: Some("pending".to_string()),
        ..Default::default()
    }
}

/// A valid OrderNote; n makes its values differ.
pub fn new_order_note(n: i32) -> mongorust_mongodb_repositories_only::entities::order::OrderNote {
    mongorust_mongodb_repositories_only::entities::order::OrderNote {
        text: Some(format!("text-{n}")),
        at: Some(chrono::NaiveDate::from_ymd_opt(2026, 1, (n % 28 + 1) as u32).expect("a date").and_hms_opt(12, 0, 0).expect("a time").and_utc()),
        ..Default::default()
    }
}

/// A valid Country that is not stored yet; n makes its unique values differ.
pub fn new_country(n: i32) -> Country {
    Country {
        document_id: Some(format!("id-{n}")),
        id: Some(f64::from(n) + 0.5),
        name: Some(format!("name-{n}")),
        ..Default::default()
    }
}

/// A stored Country.
pub async fn add_country(uow: &dyn UnitOfWork, n: i32) -> Country {
    let entity = new_country(n);
    uow.countries().insert(entity).await.expect("a stored Country")
}

